  {
    titulo = "Dalaran y Ventormenta: la llegada a la Alianza", min = 12, max = 13,
    entrenar = "En Ventormenta tu instructor de pícaro es Osborne, en la taberna del Casco Antiguo; en Forjaz, Hulfdan Barbanegra.",
    equipo = "En Ventormenta hay subasta y vendedores de armas de una mano.",
    profesion = "En Ventormenta: Minería de oficial con Gelman Petramano y Desuello de oficial con Maris Granger.",
    pasos = {
      { t = "La nave te deja en Dalaran, en las Montañas de Alterac: entrega [La ciudad mágica de Dalaran] a Denaaris Stargale y acepta [Bienvenido a Azeroth]. A su lado, cruza el Portal Skyborne: te lleva a Ventormenta.", wp = { { m = 1416, z = "Montañas de Alterac", x = 12.3, y = 56.3, n = "Entregar: La ciudad mágica de Dalaran (Denaaris Stargale)", q = 94946, a = "T" }, { m = 1416, z = "Montañas de Alterac", x = 12.3, y = 56.3, n = "Recoger: Bienvenido a Azeroth (Denaaris Stargale)", q = 94947, a = "A" } } },
      { t = "En Ventormenta sube al castillo, al nordeste de la ciudad: entrega [Bienvenido a Azeroth] a Alto Señor Bolvar Fordragon y acepta [Viaje a la Colina del Centinela], que se entrega en la Colina del Centinela, en Poniente. Activa el vuelo con Dungar Tragolargo, en el Distrito de Mercaderes.", wp = { { m = 1453, z = "Ciudad de Ventormenta", x = 80.2, y = 38.4, n = "Entregar: Bienvenido a Azeroth (Alto Señor Bolvar Fordragon)", q = 94947, a = "T" }, { m = 1453, z = "Ciudad de Ventormenta", x = 80.2, y = 38.4, n = "Recoger: Viaje a la Colina del Centinela (Alto Señor Bolvar Fordragon)", q = 98021, a = "A" }, { m = 1453, z = "Ciudad de Ventormenta", x = 71.3, y = 72.2, n = "Dungar Tragolargo", npc = 352 } } },
      { t = "Nivel 12: en la taberna del Casco Antiguo entrena con Osborne: Patada y Parada. Al hablar con el instructor elige entrenar: la guía aprende sola lo recomendado (Mayús para hacerlo a mano).", wp = { { m = 1453, z = "Ciudad de Ventormenta", x = 77.4, y = 65.3, n = "Osborne", npc = 918 } }, comprobar = { hechizos = { 1766 } } },
      { t = "Sal de Ventormenta por el Valle de los Héroes y sigue el camino hasta Villadorada: en la posada, Keryn Sylvius te da [Busca el SI: 7]. Vuelve a Ventormenta: en el Casco Antiguo, entrégala a Maestro Mathias Shaw, en la sede del IV:7, y acepta [El robo].", wp = { { m = 1429, z = "Bosque de Elwynn", x = 43.9, y = 65.9, n = "Recoger: Busca el SI: 7 (Keryn Sylvius)", q = 2205, a = "A" }, { m = 1453, z = "Ciudad de Ventormenta", x = 78.3, y = 70.7, n = "Entregar: Busca el SI: 7 (Maestro Mathias Shaw)", q = 2205, a = "T" }, { m = 1453, z = "Ciudad de Ventormenta", x = 78.3, y = 70.7, n = "Recoger: El robo (Maestro Mathias Shaw)", q = 2206, a = "A" } } },

    },
  },
  {
    titulo = "Páramos de Poniente", min = 11, max = 15,
    entrenar = "Nivel 20 = entrenamiento en Ventormenta con Osborne, en el Casco Antiguo: Sigilo (rango 2); Ruptura es opcional. Talentos 18-20: Desviar (paras más golpes). Al 20 empieza tu misión de los venenos: antes necesitas 80 de Forzar cerraduras.",
    equipo = "Objetivo: completar la cadena [La hermandad de los Defias] hasta Las Minas de la Muerte. La última parte da a elegir la <Túnica de Páramos de Poniente>, de cuero.",
    profesion = "Desuello: lobos, jabalíes y buitres de Poniente dan <Cuero ligero> y <Cuero medio>. Minería: cobre y estaño en las colinas. Primeros auxilios: <Venda de lana>. Forzar cerraduras: usa Robar con los humanoides antes de atacarlos: a veces llevan cajas cerradas que suben la habilidad.",
    pasos = {
      { t = "Misión de clase: sal de Ventormenta por el Valle de los Héroes y baja al sur, pasada Villadorada, hasta el Embarcadero de Jerod, junto al río. Mata al Maestro de embarcadero Defias y coge el horario de [El robo]: se lo darás a Maestro Mathias Shaw al 20.", wp = { { m = 1429, z = "Bosque de Elwynn", x = 48.1, y = 87.0, n = "Objetivo: El robo", q = 2206, a = "C" } } },
      { t = "Sigue el camino al oeste por Elwynn hasta Poniente (desde Ventormenta, sal por el Valle de los Héroes). Al entrar, en la granja de los Cejade, Verna Cejade te da [Estofado de los Páramos de Poniente] y [La pobre y vieja Blanchy], y Granjero Cejade, [La reliquia olvidada].", wp = { { m = 1436, z = "Páramos de Poniente", x = 59.9, y = 19.4, n = "Recoger: Estofado de los Páramos de Poniente (Verna Cejade)", q = 36, a = "A" }, { m = 1436, z = "Páramos de Poniente", x = 59.9, y = 19.4, n = "Recoger: La pobre y vieja Blanchy (Verna Cejade)", q = 151, a = "A" }, { m = 1436, z = "Páramos de Poniente", x = 60.0, y = 19.4, n = "Recoger: La reliquia olvidada (Granjero Cejade)", q = 64, a = "A" } } },
      { t = "Granja de los Saldean, al sur por el camino: entrega [Estofado de los Páramos de Poniente] a Salma Saldean y acepta [Estofado de los Páramos de Poniente] y [Pastel de hígado de dentosangre]. Granjero Saldean te da [Campos de la muerte].", wp = { { m = 1436, z = "Páramos de Poniente", x = 56.4, y = 30.5, n = "Entregar: Estofado de los Páramos de Poniente (Salma Saldean)", q = 36, a = "T" }, { m = 1436, z = "Páramos de Poniente", x = 56.4, y = 30.5, n = "Recoger: Estofado de los Páramos de Poniente (Salma Saldean)", q = 38, a = "A" }, { m = 1436, z = "Páramos de Poniente", x = 56.4, y = 30.5, n = "Recoger: Pastel de hígado de dentosangre (Salma Saldean)", q = 22, a = "A" }, { m = 1436, z = "Páramos de Poniente", x = 56.0, y = 31.2, n = "Recoger: Campos de la muerte (Granjero Saldean)", q = 9, a = "A" } } },
      { t = "Por los campos de alrededor: mata gólems de la cosecha ([Campos de la muerte]), jabalíes dentosangre (hígados de [Pastel de hígado de dentosangre]) y buitres, jabalíes y arañas para la carne de [Estofado de los Páramos de Poniente]. Recoge también las avenas de [La pobre y vieja Blanchy] y busca la reliquia de [La reliquia olvidada] donde te marca la flecha.", wp = { { m = 1436, z = "Páramos de Poniente", x = 53.5, y = 31.7, n = "Objetivo: Campos de la muerte", q = 9, a = "C" }, { m = 1436, z = "Páramos de Poniente", x = 56.0, y = 43.1, n = "Objetivo: Pastel de hígado de dentosangre", q = 22, a = "C" }, { m = 1436, z = "Páramos de Poniente", x = 53.4, y = 22.9, n = "Objetivo: Estofado de los Páramos de Poniente", q = 38, a = "C" }, { m = 1436, z = "Páramos de Poniente", x = 56.1, y = 17.3, n = "Objetivo: La pobre y vieja Blanchy", q = 151, a = "C" }, { m = 1436, z = "Páramos de Poniente", x = 49.3, y = 19.3, n = "Objetivo: La reliquia olvidada", q = 64, a = "C" } } },
