  {
    titulo = "Vuelta a Ventormenta", min = 20, max = 20,
    entrenar = "Nivel 20 = entrenamiento en Ventormenta con Osborne, en el Casco Antiguo: Sigilo (rango 2); Ruptura es opcional. Talentos 18-20: Desviar (paras más golpes). Al 20 empieza tu misión de los venenos: antes necesitas 80 de Forzar cerraduras.",
    equipo = "Objetivo: completar la cadena [La hermandad de los Defias] hasta Las Minas de la Muerte. La última parte da a elegir la <Túnica de Páramos de Poniente>, de cuero. Mazmorras (opcional): las de tu nivel dan mucha experiencia, por sus enemigos y por sus misiones, y conviene hacerlas; tú decides si vas.",
    profesion = "Desuello: lobos, jabalíes y buitres de Poniente dan <Cuero ligero> y <Cuero medio>. Minería: cobre y estaño en las colinas. Primeros auxilios: <Venda de lana>. Forzar cerraduras: usa Robar con los humanoides antes de atacarlos: a veces llevan cajas cerradas que suben la habilidad.",
    pasos = {
      { t = "Vuela de Menethil a Ventormenta. En el Casco Antiguo, Renzik \"Cuchillo\" recibe [Una regia sacudida] y te da [Cita en Crestagrana]: se entrega en Villa del Lago (Crestagrana), adonde irás al 20.", wp = { { m = 1453, z = "Ciudad de Ventormenta", x = 78.3, y = 71.1, n = "Entregar: Una regia sacudida (Renzik \"Cuchillo\")", q = 2298, a = "T" }, { m = 1453, z = "Ciudad de Ventormenta", x = 78.3, y = 71.1, n = "Recoger: Cita en Crestagrana (Renzik \"Cuchillo\")", q = 2281, a = "A" } } },
      { t = "Nivel 20: vuela a Ventormenta y entrena con Osborne en el Casco Antiguo: Sigilo (rango 2) y, si quieres, Ruptura. El Veneno atroz (opcional: ralentiza) te lo venderá cuando sepas Venenos. Al hablar con el instructor elige entrenar: la guía aprende sola lo recomendado (Mayús para hacerlo a mano).", wp = { { m = 1453, z = "Ciudad de Ventormenta", x = 77.4, y = 65.3, n = "Osborne", npc = 918 } }, comprobar = { hechizos = { 1785 } } },
      { t = "Al lado, entrega [El robo] a Maestro Mathias Shaw, que te da [Mathias y los Defias]: tu misión de los venenos. Para acabarla necesitas 80 de Forzar cerraduras: la subirás en Crestagrana.", wp = { { m = 1453, z = "Ciudad de Ventormenta", x = 78.3, y = 70.7, n = "Entregar: El robo (Maestro Mathias Shaw)", q = 2206, a = "T" }, { m = 1453, z = "Ciudad de Ventormenta", x = 78.3, y = 70.7, n = "Recoger: Mathias y los Defias (Maestro Mathias Shaw)", q = 2360, a = "A" } } },
    },
  },
  {
    titulo = "Montañas Crestagrana", min = 20, max = 23,
    entrenar = "Pelea así: Golpe siniestro hasta 5 puntos de combo, Hacer picadillo y Eviscerar; Patada y Gubia contra los que lanzan hechizos. Al 22: Esfumarse (para escapar) y Golpe siniestro (rango 4). Talentos: 21 Respuesta (contraataca después de parar) y 22-24 Reflejos relámpago.",
    equipo = "Busca grupo para Las Minas de la Muerte (entrada en Arroyo de la Luna, Poniente). Mazmorras (opcional): las de tu nivel dan mucha experiencia, por sus enemigos y por sus misiones, y conviene hacerlas; tú decides si vas.",
    profesion = "Forzar cerraduras: cada Arcón de prácticas del Molino de Alther, al norte del lago, sube hasta unos 70; después, cada Baúl con marcas de agua del fondo del lago, hasta 110. Desuello 75-150: <Cuero medio> de cóndores, jabalíes y arañas. Minería: estaño y plata en las colinas.",
    pasos = {
      { t = "Desde Ventormenta ve al este por Elwynn hasta Villa del Lago. Acepta [Gnolls invasores] en la entrada oeste de la zona; en Villa del Lago activa el vuelo con Ariena Tempespluma, entrega [La hermandad de los Defias] y sigue con [La hermandad de los Defias].", wp = { { m = 1433, z = "Montañas Crestagrana", x = 10.4, y = 71.3, n = "Recoger: Gnolls invasores (Guardia Parker)", q = 244, a = "A" }, { m = 1433, z = "Montañas Crestagrana", x = 25.5, y = 59.4, n = "Ariena Tempespluma", npc = 931 }, { m = 1433, z = "Montañas Crestagrana", x = 21.4, y = 45.4, n = "Entregar: La hermandad de los Defias (Wiley el Negro)", q = 65, a = "T" }, { m = 1433, z = "Montañas Crestagrana", x = 21.4, y = 45.4, n = "Recoger: La hermandad de los Defias (Wiley el Negro)", q = 132, a = "A" } } },
      { t = "En el muelle del oeste de Villa del Lago entrega [Cita en Crestagrana] a Lucius y acepta [Molino de Alther]: te da las <Herramientas de ladrón>, que necesitas para Forzar cerradura.", wp = { { m = 1433, z = "Montañas Crestagrana", x = 23.0, y = 52.0, n = "Entregar: Cita en Crestagrana (Lucius)", q = 2281, a = "T" }, { m = 1433, z = "Montañas Crestagrana", x = 23.0, y = 52.0, n = "Recoger: Molino de Alther (Lucius)", q = 2282, a = "A" } } },
      { t = "Molino de Alther (al norte del lago): abre con Forzar cerradura cada Arcón de prácticas una y otra vez (se vuelve a cerrar enseguida) hasta unos 70. Con 25, abre también el Arcón de Lucius, al lado, y llévale la <Muestra de robo> a Lucius.", wp = { { m = 1433, z = "Montañas Crestagrana", x = 47.0, y = 44.7, n = "Objetivo: Molino de Alther", q = 2282, a = "C" }, { m = 1433, z = "Montañas Crestagrana", x = 23.0, y = 52.0, n = "Entregar: Molino de Alther (Lucius)", q = 2282, a = "T" } } },
      { t = "Forzar cerraduras 70-80: bucea en el lago Sempiterno y abre cada Baúl con marcas de agua que veas en el fondo (sirven hasta 110). Necesitas 80 para tu misión de los venenos, y el tope es 5 veces tu nivel.", wp = { { m = 1433, z = "Montañas Crestagrana", x = 34.3, y = 61.9, n = "Baúles del fondo del lago" }, { m = 1433, z = "Montañas Crestagrana", x = 45.2, y = 55.1, n = "Baúles del fondo del lago" } }, comprobar = { oficioMin = { { skill = 633, nombre = "Forzar cerraduras", min = 80 } } } },
      { t = "Entrega [Gnolls invasores] a Ayudante de alguacil Feldon y acepta [Evaluar la amenaza]: mata gnolls y furtivos al sur.", wp = { { m = 1433, z = "Montañas Crestagrana", x = 25.6, y = 60.0, n = "Entregar: Gnolls invasores (Ayudante de alguacil Feldon)", q = 244, a = "T" }, { m = 1433, z = "Montañas Crestagrana", x = 25.6, y = 60.0, n = "Recoger: Evaluar la amenaza (Ayudante de alguacil Feldon)", q = 246, a = "A" }, { m = 1433, z = "Montañas Crestagrana", x = 26.6, y = 82.6, n = "Objetivo: Evaluar la amenaza", q = 246, a = "C" }, { m = 1433, z = "Montañas Crestagrana", x = 25.6, y = 60.0, n = "Entregar: Evaluar la amenaza (Ayudante de alguacil Feldon)", q = 246, a = "T" } } },
