  {
    titulo = "Los venenos: la torre de Klaven", min = 22, max = 24,
    entrenar = "Al 24: Navajazo (Shank) y Eviscerar (rango 4). Con [La torre de Klaven] aprendes Venenos y el <Veneno instantáneo>: ponlo en el arma de la mano derecha (dura 30 minutos) y vuelve a ponerlo cuando se acabe.",
    equipo = "[La torre de Klaven] es de nivel 24: los zánganos de la torre son de nivel 23 y 24. Ve en Sigilo, ábrete paso de uno en uno y usa Esfumarse si se complica. Mazmorras (opcional): las de tu nivel dan mucha experiencia, por sus enemigos y por sus misiones, y conviene hacerlas; tú decides si vas.",
    profesion = "Venenos: cada veneno que haces sube 1 punto, sea cual sea, hasta 5 veces tu nivel. Compra <Polvo de Decadencia> y <Vial vacío> a Sloan McCoy o Jasper Fel, en el Casco Antiguo, y haz <Veneno instantáneo> hasta 100 o más: al 28 el rango 2 pide 120.",
    pasos = {
      { t = "Vuela de Ventormenta a la Colina del Centinela y ve al este de Poniente, junto al camino del Bosque del Ocaso: entrega [Mathias y los Defias] a Agente Kearnen y acepta [La torre de Klaven].", wp = { { m = 1436, z = "Páramos de Poniente", x = 68.5, y = 70.1, n = "Entregar: Mathias y los Defias (Agente Kearnen)", q = 2360, a = "T" }, { m = 1436, z = "Páramos de Poniente", x = 68.5, y = 70.1, n = "Recoger: La torre de Klaven (Agente Kearnen)", q = 2359, a = "A" } } },
      { t = "La torre de Klaven está al sur del agente: en Sigilo, quítale la <Llave de la torre Defias> a un Zángano defias deformado (Robar; si no la lleva, mátalo) y entra en la torre. Arriba abre el Cofre de Bosque del Ocaso con Forzar cerradura (80) y coge el <Diario de Klaven Mortwake>.", wp = { { m = 1436, z = "Páramos de Poniente", x = 69.9, y = 74.0, n = "Objetivo: La torre de Klaven", q = 2359, a = "C" } } },
      { t = "Vuelve a la Colina del Centinela, vuela a Ventormenta y entrega [La torre de Klaven] a Maestro Mathias Shaw: aprendes Venenos y el <Veneno instantáneo>. La cadena sigue con [Toque de Zanzil]: es opcional y pide un <Tubo de bronce>, que fabrican los ingenieros.", wp = { { m = 1453, z = "Ciudad de Ventormenta", x = 78.3, y = 70.7, n = "Entregar: La torre de Klaven (Maestro Mathias Shaw)", q = 2359, a = "T" } } },
      { t = "En el Casco Antiguo compra <Polvo de Decadencia> y <Vial vacío> a Sloan McCoy y haz <Veneno instantáneo> (pestaña Venenos de tus profesiones): uno para el arma de la mano derecha y unos cuantos más para subir la habilidad.", wp = { { m = 1453, z = "Ciudad de Ventormenta", x = 78.6, y = 70.9, n = "Sloan McCoy", npc = 1326 } }, comprobar = { oficios = { 40 } } },
