  {
    titulo = "Los Humedales", min = 24, max = 26,
    entrenar = "Al 24: Navajazo y Eviscerar (rango 4); al 26, Golpe bajo (abre desde Sigilo: aturde y da 2 puntos de combo) y Patada (rango 2). Talentos: 25 Ejecución impecable (Eviscerar cuesta mucha menos energía) y 26-28 Agresión.",
    equipo = "Las misiones del Puerto de Menethil dan botas y pantalones de cuero. Mazmorras (opcional): las de tu nivel dan mucha experiencia, por sus enemigos y por sus misiones, y conviene hacerlas; tú decides si vas.",
    profesion = "Forzar cerraduras 110-150: cada Baúl maltrecho de los campamentos múrloc de la costa, al norte del Puerto de Menethil. Venenos: Samor Festivus vende los reactivos en Menethil. Desuello: raptores y cocodrilos dan <Cuero medio>. A 125 aprende los rangos expertos de Minería y Desuello en Forjaz (Geofram Dedorroca y Balthus Cazarrocas).",
    pasos = {
      { t = "Usa la piedra de hogar para volver a Thelsamar, sube a la presa del norte y crúzala hasta Los Humedales. Sigue el camino hasta el Puerto de Menethil y activa el vuelo.", wp = { { m = 1437, z = "Los Humedales", x = 9.5, y = 59.7, n = "Vuelo del Puerto de Menethil" } }, comprobar = { vuelo = "Menethil" } },
