  {
    titulo = "Laderas de Trabalomas y Arathi", min = 36, max = 39,
    entrenar = "Al 36: Veneno instantáneo (rango 3, pide Venenos 160); al 38, Golpe siniestro (rango 6) y Veneno mortal (rango 2, pide 170). Cerca de Molino Tarren hay jugadores de la Horda: pasa en Sigilo y usa Esfumarse si te atacan.",
    equipo = "Cambias mucho de equipo en este rango: busca piezas de cuero de nivel 35 en la subasta. Mazmorras (opcional): las de tu nivel dan mucha experiencia, por sus enemigos y por sus misiones, y conviene hacerlas; tú decides si vas.",
    profesion = "En Stromgarde (Arathi), Deneb Camino vende <Primeros auxilios para expertos: Entre vendas> y los manuales de vendas. Forzar cerraduras 150-175: cada Baúl maltrecho del Castillo de Durnholde (Trabalomas). Venenos: Jaysin Lanyda vende los reactivos en Costasur.",
    pasos = {
      { t = "Nivel 34-38: vuelve a Villa Oscura, vuela a Ventormenta y entrena con Osborne: Sprint (rango 2), Veneno instantáneo (rango 3) y, al 38, Golpe siniestro (rango 6) y Veneno mortal (rango 2). Al hablar con el instructor elige entrenar: la guía aprende sola lo recomendado (Mayús para hacerlo a mano).", wp = { { m = 1453, z = "Ciudad de Ventormenta", x = 77.4, y = 65.3, n = "Osborne", npc = 918 } }, comprobar = { hechizos = { 8696 } } },
