  {
    titulo = "Marjal Revolcafango", min = 39, max = 42,
    entrenar = "Nivel 40: Eviscerar (rango 6) y Sigilo (rango 3). Talento 40: Subidón de adrenalina (recuperas energía el doble de rápido 15 s: para los combates difíciles). Talentos 41-42: Especialización en doble arma.",
    equipo = "Al 40 compra la montura. Busca en la subasta piezas de cuero 'del mono' o 'del tigre' y un arma lenta para la mano derecha. Mazmorras (opcional): las de tu nivel dan mucha experiencia, por sus enemigos y por sus misiones, y conviene hacerlas; tú decides si vas.",
    profesion = "En Theramore: [Atenciones médicas] de Primeros auxilios con Doctor Gustaf VanHowzen (225). Desuello y Minería: el Marjal tiene muchas bestias y filones de hierro y mitril.",
    pasos = {
      { t = "Nivel 40: vuela de Costasur a Forjaz y entrena con Hulfdan Barbanegra: Eviscerar (rango 6) y Sigilo (rango 3). Guarda oro para la montura. Al hablar con el instructor elige entrenar: la guía aprende sola lo recomendado (Mayús para hacerlo a mano).", wp = { { m = 1455, z = "Forjaz", x = 52.0, y = 14.8, n = "Hulfdan Barbanegra", npc = 5165 } }, comprobar = { hechizos = { 8624 } } },
      { t = "Montura: vuela a Ventormenta y ve al este de Elwynn. En el campamento maderero del este aprende equitación con Randal Predatio y compra un caballo a Katie Hunter.", wp = { { m = 1429, z = "Bosque de Elwynn", x = 84.3, y = 64.9, n = "Randal Predatio", npc = 4732 }, { m = 1429, z = "Bosque de Elwynn", x = 84.2, y = 65.5, n = "Katie Hunter", npc = 384 } } },
      { t = "Vuela a Menethil y coge el barco a Theramore. Compra 3 <Especias calmantes> a Helenia Olden, que las pedirá \"Ojolodo\" Jarl. Morgan Stern te da [Sopa de fangorroca con tropezones]: tortugas Fangorroca en la costa del Marjal. La segunda parte ([... con tropezones]) es del Pantano de las Penas: no la cojas.", wp = { { m = 1445, z = "Marjal Revolcafango", x = 66.4, y = 51.5, n = "Helenia Olden", npc = 4897 }, { m = 1445, z = "Marjal Revolcafango", x = 66.3, y = 45.5, n = "Recoger: Sopa de fangorroca con tropezones (Morgan Stern)", q = 1204, a = "A" }, { m = 1445, z = "Marjal Revolcafango", x = 59.5, y = 52.9, n = "Objetivo: Sopa de fangorroca con tropezones", q = 1204, a = "C" }, { m = 1445, z = "Marjal Revolcafango", x = 66.3, y = 45.5, n = "Entregar: Sopa de fangorroca con tropezones (Morgan Stern)", q = 1204, a = "T" } } },
      { t = "Marjal: [¡Qué hambre!] (cabezas de aleta de fango al norte).", wp = { { m = 1445, z = "Marjal Revolcafango", x = 35.1, y = 38.3, n = "Recoger: ¡Qué hambre! (Fangolpe Piesucio)", q = 1177, a = "A" }, { m = 1445, z = "Marjal Revolcafango", x = 57.7, y = 15.2, n = "Objetivo: ¡Qué hambre!", q = 1177, a = "C" }, { m = 1445, z = "Marjal Revolcafango", x = 35.1, y = 38.3, n = "Entregar: ¡Qué hambre! (Fangolpe Piesucio)", q = 1177, a = "T" } } },
      { t = "Pantano de la Luz: dale las especias a \"Ojolodo\" Jarl ([Especias calmantes]) y haz [Jarl necesita ojos]: arañas Niebla Negra, al oeste.", wp = { { m = 1445, z = "Marjal Revolcafango", x = 55.4, y = 26.3, n = "Recoger: Especias calmantes (\"Ojolodo\" Jarl)", q = 1218, a = "A" }, { m = 1445, z = "Marjal Revolcafango", x = 55.4, y = 26.3, n = "Entregar: Especias calmantes (\"Ojolodo\" Jarl)", q = 1218, a = "T" }, { m = 1445, z = "Marjal Revolcafango", x = 55.4, y = 26.3, n = "Recoger: Jarl necesita ojos (\"Ojolodo\" Jarl)", q = 1206, a = "A" }, { m = 1445, z = "Marjal Revolcafango", x = 32.6, y = 22.1, n = "Objetivo: Jarl necesita ojos", q = 1206, a = "C" }, { m = 1445, z = "Marjal Revolcafango", x = 55.4, y = 26.3, n = "Entregar: Jarl necesita ojos (\"Ojolodo\" Jarl)", q = 1206, a = "T" } } },
