    pasos = {
      { t = "Vuelve a los Reinos del Este: vuela de Vista Eterna a Auberdine, coge el barco a Menethil y vuela a Forjaz. Entrena con Hulfdan Barbanegra todo lo que te falte: Golpe siniestro (rango 8), Eviscerar (rango 8), Veneno instantáneo (rango 5), Veneno mortal (rango 4) y, al 58, Sprint (rango 3) y Patada (rango 4). Al hablar con el instructor elige entrenar: la guía aprende sola lo recomendado (Mayús para hacerlo a mano).", wp = { { m = 1455, z = "Forjaz", x = 52.0, y = 14.8, n = "Hulfdan Barbanegra", npc = 5165 } }, comprobar = { hechizos = { 11300 } } },
