R.talentosIntro = "Combate con dos armas: Golpe siniestro, Hacer picadillo y Navajazo. Respuesta al 21, Aluvión de acero al 30, Destello de acero al 35 y Subidón de adrenalina al 40; después, Asesinato para tener más críticos y Sangre fría al 60. Nombres en español con el inglés entre paréntesis."
R.talentos = {
  { d = 10, h = 11, rama = "Combate", fila = 1, nombre = "Golpes eficientes (Efficient Strikes)", puntos = "2/2", nota = "Nuevo en Forever: Golpe siniestro cuesta menos energía.", icono = "Interface\\Icons\\Spell_Shadow_RitualOfSacrifice" },
  { d = 12, h = 14, rama = "Combate", fila = 1, nombre = "Golpe de gracia (Coup de Grace)", puntos = "3/3", nota = "Eviscerar hace más daño. Con estos 5 puntos abres la fila 2.", icono = "Interface\\Icons\\Ability_Rogue_Eviscerate" },
  { d = 15, h = 17, rama = "Combate", fila = 2, nombre = "Precisión (Precision)", puntos = "3/3", nota = "Fallas menos golpes.", icono = "Interface\\Icons\\Ability_Marksmanship" },
  { d = 18, h = 20, rama = "Combate", fila = 2, nombre = "Desviar (Deflection)", puntos = "3/3", nota = "Paras más golpes. Con estos 10 puntos abres la fila 3.", icono = "Interface\\Icons\\Ability_Parry" },
  { d = 21, h = 21, rama = "Combate", fila = 3, nombre = "Respuesta (Riposte)", puntos = "1/1", nota = "Después de parar un golpe, contraataca: pega fuerte y desarma al enemigo unos segundos.", icono = "Interface\\Icons\\Ability_Warrior_Challange" },
  { d = 22, h = 24, rama = "Combate", fila = 1, nombre = "Reflejos relámpago (Lightning Reflexes)", puntos = "3/5", nota = "Esquivas más. Con estos 15 puntos abres la fila 4.", icono = "Interface\\Icons\\Spell_Nature_Invisibilty" },
  { d = 25, h = 25, rama = "Combate", fila = 4, nombre = "Ejecución impecable (Flawless Execution)", puntos = "1/1", nota = "Nuevo: Eviscerar cuesta mucha menos energía.", icono = "Interface\\Icons\\INV_Sword_35" },
  { d = 26, h = 28, rama = "Combate", fila = 4, nombre = "Agresión (Aggression)", puntos = "3/3", nota = "Golpe siniestro y Eviscerar hacen más daño.", icono = "Interface\\Icons\\Ability_Racial_Avatar" },
  { d = 29, h = 29, rama = "Combate", fila = 4, nombre = "Pericia con armas (Weapon Expertise)", puntos = "1/2", nota = "El enemigo esquiva y para menos tus golpes. Con estos 20 puntos abres la fila 5.", icono = "Interface\\Icons\\Spell_Holy_BlessingOfStrength" },
  { d = 30, h = 30, rama = "Combate", fila = 5, nombre = "Aluvión de acero (Blade Flurry)", puntos = "1/1", nota = "Atacas más rápido y tus golpes dan también a un enemigo cercano: úsalo cuando pelees con dos.", icono = "Interface\\Icons\\Ability_Warrior_PunishingBlow" },
  { d = 31, h = 34, rama = "Combate", fila = 5, nombre = "Tajos y cortes (Hack and Slash)", puntos = "4/5", nota = "Depende del arma: con hacha o espada, golpes extra; con daga o arma de puño, más críticos; con maza, ignoras armadura. Con estos 25 puntos abres la fila 6.", icono = "Interface\\Icons\\INV_Sword_27" },
  { d = 35, h = 39, rama = "Combate", fila = 6, nombre = "Destello de acero (Flash of Steel)", puntos = "5/5", nota = "Nuevo: Navajazo te da más energía y se recarga antes. Con 30 puntos abres la fila 7.", icono = "Interface\\Icons\\Ability_Rogue_RestlessBlades" },
  { d = 40, h = 40, rama = "Combate", fila = 7, nombre = "Subidón de adrenalina (Adrenaline Rush)", puntos = "1/1", nota = "Recuperas energía el doble de rápido 15 segundos: guárdalo para los combates difíciles.", icono = "Interface\\Icons\\Spell_Shadow_ShadowWordDominate" },
  { d = 41, h = 42, rama = "Combate", fila = 5, nombre = "Especialización en doble arma (Dual Wield Specialization)", puntos = "2/2", nota = "Más daño con el arma de la mano izquierda.", icono = "Interface\\Icons\\Ability_DualWield" },
  { d = 43, h = 43, rama = "Combate", fila = 4, nombre = "Pericia con armas (Weapon Expertise)", puntos = "2/2", nota = "Completa el talento.", icono = "Interface\\Icons\\Spell_Holy_BlessingOfStrength" },
  { d = 44, h = 44, rama = "Combate", fila = 5, nombre = "Tajos y cortes (Hack and Slash)", puntos = "5/5", nota = "Completa el talento.", icono = "Interface\\Icons\\INV_Sword_27" },
  { d = 45, h = 49, rama = "Asesinato", fila = 1, nombre = "Malicia (Malice)", puntos = "5/5", nota = "Más críticos con todos tus ataques y con los venenos.", icono = "Interface\\Icons\\Ability_Racial_BloodRage" },
  { d = 50, h = 52, rama = "Asesinato", fila = 2, nombre = "Despiadado (Ruthlessness)", puntos = "3/3", nota = "Tus remates pueden dejarte un punto de combo para el siguiente enemigo.", icono = "Interface\\Icons\\Ability_Druid_Disembowel" },
  { d = 53, h = 54, rama = "Asesinato", fila = 2, nombre = "Hacer picadillo mejorado (Improved Slice and Dice)", puntos = "2/3", nota = "Hacer picadillo dura más. Con estos 10 puntos abres la fila 3.", icono = "Interface\\Icons\\Ability_Rogue_SliceDice" },
  { d = 55, h = 56, rama = "Asesinato", fila = 3, nombre = "Letalidad (Lethality)", puntos = "2/2", nota = "Los críticos de Golpe siniestro hacen más daño.", icono = "Interface\\Icons\\Ability_CriticalStrike" },
  { d = 57, h = 58, rama = "Asesinato", fila = 3, nombre = "Vigor", puntos = "2/2", nota = "Más energía máxima.", icono = "Interface\\Icons\\Spell_Nature_EarthBindTotem" },
  { d = 59, h = 59, rama = "Asesinato", fila = 2, nombre = "Hacer picadillo mejorado (Improved Slice and Dice)", puntos = "3/3", nota = "Completa el talento. Con estos 15 puntos abres la fila 4.", icono = "Interface\\Icons\\Ability_Rogue_SliceDice" },
  { d = 60, h = 60, rama = "Asesinato", fila = 4, nombre = "Sangre fría (Cold Blood)", puntos = "1/1", nota = "Tu siguiente golpe es crítico seguro: úsalo con Eviscerar a 5 puntos de combo. Total al 60: 35 Combate / 16 Asesinato.", icono = "Interface\\Icons\\Spell_Ice_Lament" },
}

R.profesiones = {
  { nombre = "Minería", skill = 186, icono = "Interface\\Icons\\Trade_Mining", intro = "Mina cada veta que veas: da puntos y oro para los entrenamientos. Fundir en una forja también da puntos. Rangos: aprendiz con Messana Crestwind en Shen'dar (Isla Zephras) o con Kelsey Fargo en la entrada de la Mina del Eco (también vende el <Pico de minero>); oficial con Gelman Petramano en el Distrito de los Enanos de Ventormenta o con Geofram Dedorroca en Forjaz (minería 50 y nivel 10); experto y artesano con Geofram Dedorroca (125 y nivel 20; 200 y nivel 25).", pasos = {
    { d = 1, h = 65, icono = "Interface\\Icons\\inv_ore_copper_01", t = "<Mineral de cobre>: vetas de cobre de la Isla Zephras, Elwynn, Loch Modan y Poniente. Funde <Lingote de cobre> (1 <Mineral de cobre>) en la forja de Villadorada, de Ventormenta o de Forjaz. A 50 aprende el rango oficial.", crea = { 2770, 2840 } },
    { d = 65, h = 125, icono = "Interface\\Icons\\inv_ore_tin_01", t = "<Mineral de estaño> y <Mineral de plata>: vetas de estaño y de plata en Crestagrana, Los Humedales y el Bosque del Ocaso. Funde <Lingote de estaño> (1 <Mineral de estaño>), <Lingote de plata> (1 <Mineral de plata>) y <Lingote de bronce> (1 <Lingote de cobre> y 1 <Lingote de estaño>). A 125 aprende el rango experto.", crea = { 2771, 3576, 2842, 2841 } },
    { d = 125, h = 175, icono = "Interface\\Icons\\inv_ore_iron_01", t = "<Hierro> y <Mineral de oro>: filones de hierro y de oro en Desolace, Las Mil Agujas, la Vega de Tuercespina y Arathi. Funde <Lingote de hierro> (1 <Hierro>) y <Lingote de oro> (1 <Mineral de oro>).", crea = { 2772, 3575, 3577 } },
    { d = 175, h = 250, icono = "Interface\\Icons\\inv_ore_mithril_02", t = "<Mineral de mitril>: filones de mitril en Tanaris, Feralas, las Tierras del Interior y las Tierras Inhóspitas. Funde <Lingote de mitril> (1 <Mineral de mitril>). A 200 aprende el rango artesano. Desde 230 también la veraplata: <Lingote de veraplata> (1 <Veraplata>).", crea = { 3858, 3860, 6037 } },
    { d = 250, h = 300, icono = "Interface\\Icons\\inv_ore_thorium_02", t = "<Torio>: vetas pequeñas de torio en Un'Goro, Frondavil, Cuna del Invierno y las Tierras de la Peste; desde 275, también las ricas. Funde <Lingote de torio> (1 <Torio>).", crea = { 10620, 12359 } },
  } },
  { nombre = "Desuello", skill = 393, icono = "Interface\\Icons\\INV_Misc_Pelt_Wolf_01", intro = "Desuella todas las bestias que mates: el cuero se vende bien. Las de nivel 10 o menos valen desde el principio; después, nivel 20 pide 100, nivel 30 pide 150, nivel 40 pide 200 y así hasta 300. Rangos: aprendiz con Mendalass Tattermend en Shen'dar (Isla Zephras) o con Riley Peltskinner, al oeste de la abadía de Villanorte (también vende el <Cuchillo para desollar>); oficial con Maris Granger en el Casco Antiguo de Ventormenta o con Balthus Cazarrocas en Forjaz (50 y nivel 10); experto y artesano con Balthus Cazarrocas (125 y nivel 20; 200 y nivel 25).", pasos = {
    { d = 1, h = 75, icono = "Interface\\Icons\\inv_misc_leatherscrap_03", t = "<Cuero ligero> y <Restos de cuero estropeado>: lobos, jabalíes y osos de la Isla Zephras, Elwynn y Loch Modan. En Villadorada, [Pieles de lobo bastas] pide pieles de lobo. A 50 aprende el rango oficial con Maris Granger o con Balthus Cazarrocas.", crea = { 2318 } },
    { d = 75, h = 150, icono = "Interface\\Icons\\inv_misc_leatherscrap_05", t = "<Cuero medio>: bestias de Poniente, Crestagrana, Los Humedales y el Bosque del Ocaso. A 125 aprende el rango experto.", crea = { 2319 } },
    { d = 150, h = 225, icono = "Interface\\Icons\\inv_misc_leatherscrap_07", t = "<Cuero pesado>: bestias de Las Mil Agujas, Desolace, la Vega de Tuercespina, Arathi y el Marjal Revolcafango. A 200 aprende el rango artesano.", crea = { 4234 } },
    { d = 225, h = 300, icono = "Interface\\Icons\\inv_misc_leatherscrap_08", t = "<Cuero grueso> y después <Cuero basto>: bestias de Tanaris, Feralas, las Tierras del Interior, Un'Goro y Cuna del Invierno.", crea = { 4304 } },
  } },
  { nombre = "Primeros auxilios", corto = "Auxilios", skill = 129, icono = "Interface\\Icons\\Spell_Holy_SealOfSacrifice", intro = "No ocupa una de tus dos profesiones y en Forever también hace pociones de curación. Instructores: Naleeia Tattermend en Shen'dar y Melasa Fairmend en Valanaar (Isla Zephras), Michelle Belle en Villadorada, Shaina Fuller en la Plaza de la Catedral de Ventormenta y Nissa Pirorroca en Forjaz. A 125 compra <Primeros auxilios para expertos: Entre vendas> a Deneb Camino en Stromgarde (Arathi). A 225 haz [Atenciones médicas] con Doctor Gustaf VanHowzen en Theramore (nivel 35).", pasos = {
    { d = 1, h = 40, icono = "Interface\\Icons\\inv_misc_bandage_15", t = "<Venda de lino> (1 <Paño de lino>). Con hierbas también vale <Poción de curación menor> (<Flor de paz>, <Especias suaves> y <Vial vacío>) hasta 75.", mat = { { 2589, 1, "Paño de lino" } }, crea = { 1251, 118 } },
    { d = 40, h = 80, icono = "Interface\\Icons\\inv_misc_bandage_18", t = "<Venda de lino pesado> (2 <Paño de lino>).", mat = { { 2589, 2, "Paño de lino" } }, crea = { 2581 } },
    { d = 80, h = 115, icono = "Interface\\Icons\\inv_misc_bandage_14", t = "<Venda de lana> (1 <Paño de lana>).", mat = { { 2592, 1, "Paño de lana" } }, crea = { 3530 } },
    { d = 115, h = 150, icono = "Interface\\Icons\\inv_misc_bandage_17", t = "<Venda de lana pesada> (2 <Paño de lana>). A 125 compra <Primeros auxilios para expertos: Entre vendas>, <Manual: venda de seda pesada> y <Manual: venda de paño mágico> a Deneb Camino.", mat = { { 2592, 2, "Paño de lana" } }, crea = { 3531 } },
    { d = 150, h = 180, icono = "Interface\\Icons\\inv_misc_bandage_01", t = "<Venda de seda> (1 <Paño de seda>).", mat = { { 4306, 1, "Paño de seda" } }, crea = { 6450 } },
    { d = 180, h = 210, icono = "Interface\\Icons\\inv_misc_bandage_02", t = "<Venda de seda pesada> (2 <Paño de seda>).", mat = { { 4306, 2, "Paño de seda" } }, crea = { 6451 } },
    { d = 210, h = 225, icono = "Interface\\Icons\\inv_misc_bandage_19", t = "<Venda de paño mágico> (1 <Tela de paño mágico>). A 225 haz [Atenciones médicas]: sin ella no pasas.", mat = { { 4338, 1, "Tela de paño mágico" } }, crea = { 8544 } },
    { d = 225, h = 240, icono = "Interface\\Icons\\inv_potion_53", t = "<Poción de curación excelente> (<Solea>, <Especias calmantes> y <Vial de cristal>) si consigues la receta (cae de enemigos); si no, <Venda de paño mágico>.", mat = { { 8838, 1, "Solea" }, { 3713, 1, "Especias calmantes" }, { 8925, 1, "Vial de cristal" } }, crea = { 3928 } },
    { d = 240, h = 260, icono = "Interface\\Icons\\inv_misc_bandage_20", t = "<Venda de paño mágico pesado> (2 <Tela de paño mágico>).", mat = { { 4338, 2, "Tela de paño mágico" } }, crea = { 8545 } },
    { d = 260, h = 275, icono = "Interface\\Icons\\inv_misc_bandage_11", t = "<Venda de paño rúnico> (1 <Paño rúnico>).", mat = { { 14047, 1, "Paño rúnico" } }, crea = { 14529 } },
    { d = 275, h = 300, icono = "Interface\\Icons\\inv_potion_54", t = "<Poción de curación sublime> (<Sansam dorado>, 3 <Especias calmantes> y <Vial de cristal>) si tienes la receta; si no, <Venda de paño rúnico pesada> (2 <Paño rúnico>).", mat = { { 13464, 1, "Sansam dorado" }, { 3713, 3, "Especias calmantes" }, { 8925, 1, "Vial de cristal" } }, crea = { 13446, 14530 } },
  } },
  { nombre = "Venenos", skill = 40, icono = "Interface\\Icons\\Trade_BrewPoison", intro = "En Forever, Venenos es una habilidad aparte, como Primeros auxilios: la aprendes con [La torre de Klaven] y sube 1 punto con cada veneno que haces, sea cual sea, hasta 5 veces tu nivel. Los venenos del instructor piden también un nivel de Venenos: la guía te dice cuánto. Pon el instantáneo en el arma de la mano derecha y el mortal en la izquierda. Los reactivos los venden Tynnus Lanzaveneno en Forjaz, Sloan McCoy en Ventormenta y Malissa en Villa Oscura.", pasos = {
    { d = 1, h = 120, icono = "Interface\\Icons\\ability_poisons", t = "<Veneno instantáneo> (1 <Polvo de Decadencia> y 1 <Vial vacío>): el más barato. Haz los que te deje el tope (5 veces tu nivel): a 120 y nivel 28, el instructor te vende el rango 2.", mat = { { 2928, 1, "Polvo de Decadencia" }, { 3371, 1, "Vial vacío" } }, crea = { 6947 } },
    { d = 120, h = 160, icono = "Interface\\Icons\\ability_poisons", t = "<Veneno instantáneo> (1 <Polvo de Decadencia> y 1 <Vial vacío>) para subir. Para tus armas: <Veneno instantáneo 2> (3 <Polvo de Decadencia> y 1 <Vial con plomo>) y, desde el nivel 30 y 130, <Veneno mortal> (1 <Muerteflor> y 1 <Vial con plomo>). A 160 y nivel 36, el rango 3 del instantáneo.", mat = { { 2928, 1, "Polvo de Decadencia" }, { 3371, 1, "Vial vacío" } }, crea = { 6947, 6949, 2892 } },
    { d = 160, h = 200, icono = "Interface\\Icons\\ability_poisons", t = "<Veneno instantáneo> (1 <Polvo de Decadencia> y 1 <Vial vacío>) para subir. Para tus armas: <Veneno instantáneo 3> (1 <Polvo de Deterioro> y 1 <Vial con plomo>) y, desde el nivel 38 y 170, <Veneno mortal 2> (2 <Muerteflor> y 1 <Vial con plomo>). A 200 y nivel 44, el rango 4 del instantáneo.", mat = { { 2928, 1, "Polvo de Decadencia" }, { 3371, 1, "Vial vacío" } }, crea = { 6947, 6950, 2893 } },
    { d = 200, h = 240, icono = "Interface\\Icons\\ability_poisons", t = "<Veneno instantáneo> (1 <Polvo de Decadencia> y 1 <Vial vacío>) para subir. Para tus armas: <Veneno instantáneo 4> (2 <Polvo de Deterioro> y 1 <Vial de cristal>) y, desde el nivel 46 y 210, <Veneno mortal 3> (3 <Muerteflor> y 1 <Vial de cristal>). A 240 y nivel 52, el rango 5 del instantáneo.", mat = { { 2928, 1, "Polvo de Decadencia" }, { 3371, 1, "Vial vacío" } }, crea = { 6947, 8926, 8984 } },
    { d = 240, h = 280, icono = "Interface\\Icons\\ability_poisons", t = "<Veneno instantáneo> (1 <Polvo de Decadencia> y 1 <Vial vacío>) para subir. Para tus armas: <Veneno instantáneo 5> (3 <Polvo de Deterioro> y 1 <Vial de cristal>) y, desde el nivel 54 y 250, <Veneno mortal 4> (5 <Muerteflor> y 1 <Vial de cristal>). A 280 y nivel 60, el rango 6 del instantáneo.", mat = { { 2928, 1, "Polvo de Decadencia" }, { 3371, 1, "Vial vacío" } }, crea = { 6947, 8927, 8985 } },
    { d = 280, h = 300, icono = "Interface\\Icons\\ability_poisons", t = "<Veneno instantáneo> (1 <Polvo de Decadencia> y 1 <Vial vacío>) hasta 300. Al 60, para tus armas: <Veneno instantáneo 6> (4 <Polvo de Deterioro> y 1 <Vial de cristal>) y <Veneno mortal 4>.", mat = { { 2928, 1, "Polvo de Decadencia" }, { 3371, 1, "Vial vacío" } }, crea = { 6947, 8928 } },
  } },
  { nombre = "Forzar cerraduras", corto = "Cerraduras", skill = 633, icono = "Interface\\Icons\\Spell_Nature_MoonKey", intro = "En Forever, Forzar cerraduras es una habilidad aparte: la aprendes al 16 con Forzar cerradura en el instructor de pícaro y necesitas las <Herramientas de ladrón> de [Molino de Alther]. Sube al abrir cerraduras que no te quedan fáciles, hasta 5 veces tu nivel. Usa Robar con los humanoides antes de atacarlos: las cajas de trastos que llevan también suben la habilidad.", pasos = {
    { d = 1, h = 70, icono = "Interface\\Icons\\Spell_Nature_MoonKey", t = "Cada Arcón de prácticas del Molino de Alther (Crestagrana, al norte del lago Sempiterno): ábrelo una y otra vez, se vuelve a cerrar enseguida. Con 25, abre también el Arcón de Lucius para [Molino de Alther]." },
    { d = 70, h = 110, icono = "Interface\\Icons\\inv_box_01", t = "Cada Baúl con marcas de agua del fondo del lago Sempiterno (Crestagrana): bucea y ábrelo. Desde 70 también sube cada <Caja de trastos desgastada> que robas." },
    { d = 110, h = 150, icono = "Interface\\Icons\\Spell_Nature_MoonKey", t = "Cada Baúl maltrecho de los campamentos múrloc al norte del Puerto de Menethil (Los Humedales)." },
    { d = 150, h = 175, icono = "Interface\\Icons\\Spell_Nature_MoonKey", t = "Cada Baúl maltrecho del Castillo de Durnholde (Laderas de Trabalomas), por los patios y las torres." },
    { d = 175, h = 250, icono = "Interface\\Icons\\inv_box_03", t = "Cada <Caja de trastos robusta> que robas a los humanoides de nivel 40 o más y los arcones que caen. Si quieres ir más rápido: cada Baúl abollado de la Fortaleza de Angor (Tierras Inhóspitas)." },
    { d = 250, h = 300, icono = "Interface\\Icons\\inv_box_03", t = "Cada <Caja de trastos pesada> que robas a los humanoides de nivel 50 o más y los arcones de mitril y de torio. A 280 abres las puertas de las Profundidades de Roca Negra." },
  } },
}

