  { id = 1329283, c = "comprar", nota = "Nuevo en Forever: golpe con el arma de la mano izquierda que te da energía. Úsalo cada vez que esté listo." },
  { id = 1328825, c = "comprar", nota = "Nuevo en Forever: fuera de combate y con la energía llena, tu primer golpe cuesta menos." },
